import "./ListGroup.css"

export default function ListGroup() {

  const items = ['Auswahl1', 'Auswahl2', 'Auswahl3'];

  return (
    <ul className="GroupList">
      {items.map((item, index) => 
        <li 
        className="listItems" 
        key={item} 
        onClick={(index) => this.items = this.items.map((item, itemIndex) => {
            index === itemIndex ? item.active = 'active' : item.active = '';
            return item;})
        }>
            {item}
        </li>

      )}
    </ul>
  );
}
